                 <input required type="text" placeholder={t('username')} className={`bg-transparent outline-none w-full text-[10px] font-black italic ${isDarkMode ? 'text-white' : 'text-slate-900'} placeholder-zinc-500`} value={formData.username} onChange={e => setFormData({...formData, username: handleTextFormat(e.target.value)})} />
               </div>

               <div className={`flex items-center gap-3 p-3.5 rounded-[1.2rem] border-2 ${isDarkMode ? 'bg-black border-zinc-800' : 'bg-white border-slate-300'} relative`}>
