                          m.tips?.map((tip, idx) => {
                            const isTipLocked = idx >= 2 && !hasVipAccess;
                            const selectionDisplay = cleanSelectionText(tip.market, tip.selection);
                            if (isTipLocked) {
                              return (
                                <div key={idx} className="w-full bg-amber-500 p-4 rounded-[1.5rem] flex items-center justify-center gap-4 shadow-md border-2 border-black/10">
                                   <Lock size={18} className="text-black" />
                                   <span className="text-black font-black uppercase italic text-[11px] tracking-tight">{t('vipOnlyContent')}</span>
                                </div>
                              );
                            }
                            return (
                              <button key={idx} onClick={() => {
                                const matchId = `${m.homeTeam} vs ${m.awayTeam}`;
