                      <input required type="tel" placeholder={t('phone').toUpperCase()} className={`bg-transparent outline-none w-full text-[10px] font-black uppercase italic ${isDarkMode ? 'text-white' : 'text-slate-900'} placeholder-zinc-500`} value={formData.phone} onChange={e => setFormData({...formData, phone: e.target.value})} />
                    </div>
