                  <a href={FACEBOOK_LINK} target="_blank" className={`flex items-center gap-3 p-3.5 rounded-[1rem] border-2 ${isDarkMode ? 'bg-zinc-800/20 border-zinc-800/40 text-white' : 'bg-slate-50 border-slate-200 text-slate-900'} font-black uppercase italic text-[9px] transition-all active:scale-95`}><Facebook size={16} className="text-blue-600" /> {t('followUs').toUpperCase()}</a>
