  }, [user]);

  useEffect(() => {
    const checkAlert = async () => {
      try {
        const res = await fetch(`${FIREBASE_URL}/Alerta/chave.json`);
        const data = await res.json();
        if (data && data.mostrar === "true") {
          const dismissedToken = localStorage.getItem("dr_dismissed_alert");
          if (dismissedToken !== data.token) {
            setActiveAlert(data);
          }
        } else {
          setActiveAlert(null);
        }
      } catch (e) {}
    };
    checkAlert();
    const interval = setInterval(checkAlert, 15000);
    return () => clearInterval(interval);
  }, []);

  useEffect(() => {
    const savedUser = localStorage.getItem("dr_user");
    if (savedUser) {
      const parsed = JSON.parse(savedUser);
      setUser(parsed);
      fetch(`${FIREBASE_URL}/usuarios/${parsed.uid}.json`)
        .then(res => res.json())
        .then(data => { if (data) { setUser(data); localStorage.setItem("dr_user", JSON.stringify(data)); } })
        .catch(() => {});
    }
    const savedLang = localStorage.getItem("dr_lang") as Lang;
    if (savedLang) setLang(savedLang);
    const savedTheme = localStorage.getItem("dr_theme");
    if (savedTheme) setIsDarkMode(savedTheme === "dark");
    setIsAuthenticating(false);
  }, []);

  useEffect(() => {
    if (user) {
      loadFirebaseData();
      const stored = localStorage.getItem(`dr_tickets_${user.uid || user.username}`);
      if (stored) setSavedTickets(JSON.parse(stored));
    }
  }, [user]);

  const loadFirebaseData = async () => {
    setLoading(true);
    const dateKey = getFirebaseKey();

    try {
      // Parallel fetching from all sources including new VIP 'empates' nodes
      const [standardRes, empatesMatchesRes, empatesFichasRes] = await Promise.all([
        fetch(`${FIREBASE_URL}/predictions/${dateKey}.json`),
        fetch(`${FIREBASE_URL}/predictions/matches/empates.json`),
        fetch(`${FIREBASE_URL}/predictions/fichas/empates.json`)
      ]);

      const standardData = await standardRes.json();
      const empatesMatchesData = await empatesMatchesRes.json();
      const empatesFichasData = await empatesFichasRes.json();

      // Process Matches
      let aggregatedMatches: Match[] = [];
      if (standardData && standardData.matches) {
        const m = Array.isArray(standardData.matches) ? standardData.matches : Object.values(standardData.matches);
        aggregatedMatches = [...aggregatedMatches, ...m];
      }
      if (empatesMatchesData) {
        const m = Array.isArray(empatesMatchesData) ? empatesMatchesData : Object.values(empatesMatchesData);
        // Exclusive VIP matches
        const processed = m.map((item: any) => ({ ...item, isVipMatch: true }));
        aggregatedMatches = [...aggregatedMatches, ...processed];
      }

      // Process Accumulators
      let aggregatedFichas: Ficha[] = [];
      const rawF = standardData ? (standardData.fichas || standardData.accumulators) : null;
      if (rawF) {
        const f = Array.isArray(rawF) ? rawF : Object.values(rawF);
        aggregatedFichas = [...aggregatedFichas, ...f];
      }
      if (empatesFichasData) {
        const f = Array.isArray(empatesFichasData) ? empatesFichasData : Object.values(empatesFichasData);
        aggregatedFichas = [...aggregatedFichas, ...f];
      }

      const finalizedFichas = aggregatedFichas.map((ficha: any) => ({
        ...ficha,
        selections: ficha.selections ? (Array.isArray(ficha.selections) ? ficha.selections : Object.values(ficha.selections)) : []
      }));

      setMatches(aggregatedMatches);
      setFichas(finalizedFichas);
    } catch (e) {
      console.error("Firebase fetch error:", e);
    } finally {
      setLoading(false);
    }
  };

  const handleAuth = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);
    try {
      const res = await fetch(`${FIREBASE_URL}/usuarios.json`);
      const all = await res.json();

      if (authMode === "register") {
        const finalPhone = `${selectedCountryCode} ${formData.phone}`.trim();
        if (selectedCountryObj) {
          if (formData.phone.length < selectedCountryObj.min || formData.phone.length > selectedCountryObj.max) {
             addToast(t('invalidPhone'), "error");
             setLoading(false);
             return;
          }
        }
        if (Object.values(all || {}).some((u: any) => u.phone === finalPhone)) {
          addToast(t('accountExists'), "error");
          setLoading(false);
          return;
        }
        const uid = Date.now().toString();
        const newUser: UserProfile = { 
          uid, username: formData.username, country: formData.country === "OUTRO" ? formData.customCountry : formData.country, 
          password: formData.password, phone: finalPhone, province: formData.province, age: formData.age, isVip: false, vipExpiry: 0 
        };
        await fetch(`${FIREBASE_URL}/usuarios/${uid}.json`, { method: 'PUT', body: JSON.stringify(newUser) });
        setUser(newUser); 
        localStorage.setItem("dr_user", JSON.stringify(newUser));
        addToast(t('accCreated'));
      } else {
        const u = (Object.values(all || {}) as UserProfile[]).find(x => x?.username?.toLowerCase() === formData.username?.toLowerCase());
        if (!u || u.password !== formData.password) { addToast(t(u ? 'wrongPass' : 'userNotFound'), "error"); setLoading(false); return; }
        setUser(u); 
        localStorage.setItem("dr_user", JSON.stringify(u));
        addToast(t('welcomeBack'));
      }
    } catch { addToast(t('authError'), "error"); } finally { setLoading(false); }
  };

  const totalBetSlipOdds = useMemo(() => {
    return betSlip.reduce((acc, curr) => acc * curr.odds, 1);
  }, [betSlip]);

  const potentialWinningsCalculation = useMemo(() => {
    const total = parseFloat(manualStake || "0") * totalBetSlipOdds;
    return formatCurrency(total);
  }, [manualStake, totalBetSlipOdds]);

  const copyToClipboard = (text: string) => {
    if (!text) return;
    navigator.clipboard.writeText(text).then(() => {
      addToast(t('copySuccess'));
    });
  };

  const ageOptions = useMemo(() => {
    const opts = [];
    for(let i=17; i<=60; i++) opts.push(i);
    return opts;
  }, []);

  if (isAuthenticating) return null;

  if (!user) {
    return (
      <div className={`min-h-screen ${isDarkMode ? 'bg-[#020617] text-white' : 'bg-white text-slate-900'} flex flex-col p-6 items-center justify-center transition-all overflow-y-auto`}>
        <button onClick={() => { setIsDarkMode(!isDarkMode); localStorage.setItem("dr_theme", !isDarkMode ? "dark" : "light"); }} className="absolute top-6 right-6 p-3 rounded-full border-2 border-amber-500/20 bg-amber-500/5 text-amber-500 shadow-xl active:scale-90 transition-all">
          {isDarkMode ? <Sun size={20} /> : <Moon size={20} />}
        </button>
        <div className="w-full max-w-md space-y-5 py-5 animate-in">
          <div className="text-center space-y-2">
             <div className="bg-amber-500 w-16 h-16 rounded-[1.8rem] mx-auto flex items-center justify-center shadow-[0_0_40px_rgba(245,158,11,0.25)]">
               <Target size={38} className="text-black" />
             </div>
             <h1 className={`text-2xl font-black uppercase italic tracking-tighter ${isDarkMode ? 'text-white' : 'text-slate-900'}`}>DR <span className="text-amber-500">PALPITES</span></h1>
             <div className="space-y-1">
                <h2 className="text-amber-500 font-black italic text-lg tracking-tight leading-none">{t('promoTitle')}</h2>
                <p className={`text-[10px] font-black uppercase tracking-wider ${isDarkMode ? 'text-white' : 'text-slate-600'} leading-relaxed px-2 opacity-90`}>
                  {t('promoText')}
                </p>
             </div>
          </div>
          <div className={`p-6 rounded-[2.2rem] border-4 ${isDarkMode ? 'bg-zinc-900/80 border-zinc-800' : 'bg-slate-50 border-slate-200'} shadow-2xl backdrop-blur-xl`}>
            <div className={`flex gap-3 border-b pb-3 mb-5 ${isDarkMode ? 'border-zinc-800' : 'border-slate-200'}`}>
               <button onClick={() => setAuthMode("login")} className={`flex-1 text-[11px] font-black uppercase italic transition-all ${authMode === "login" ? "text-amber-500" : (isDarkMode ? "text-zinc-600" : "text-slate-400")}`}>{t('login')}</button>
               <button onClick={() => setAuthMode("register")} className={`flex-1 text-[11px] font-black uppercase italic transition-all ${authMode === "register" ? "text-amber-500" : (isDarkMode ? "text-zinc-600" : "text-slate-400")}`}>{t('register')}</button>
            </div>
            <form onSubmit={handleAuth} className="space-y-3">
               <div className={`flex items-center gap-3 p-3.5 rounded-[1.2rem] border-2 ${isDarkMode ? 'bg-black border-zinc-800' : 'bg-white border-slate-300'}`}>
                 <User size={16} className="text-amber-500 shrink-0" />
                 <input required type="text" placeholder={t('username')} className={`bg-transparent outline-none w-full text-[10px] font-black italic ${isDarkMode ? 'text-white' : 'text-slate-900'} placeholder-zinc-500`} value={formData.username} onChange={e => setFormData({...formData, username: handleTextFormat(e.target.value)})} />
               </div>
               <div className={`flex items-center gap-3 p-3.5 rounded-[1.2rem] border-2 ${isDarkMode ? 'bg-black border-zinc-800' : 'bg-white border-slate-300'} relative`}>
                 <Lock size={16} className="text-amber-500 shrink-0" />
                 <input required type={showPassword ? "text" : "password"} placeholder={t('password')} className={`bg-transparent outline-none w-full text-[10px] font-black uppercase italic ${isDarkMode ? 'text-white' : 'text-slate-900'} placeholder-zinc-500 pr-10`} value={formData.password} onChange={e => setFormData({...formData, password: e.target.value})} />
                 <button type="button" onClick={() => setShowPassword(!showPassword)} className="absolute right-4 text-zinc-600">{showPassword ? <EyeOff size={14} /> : <Eye size={14} />}</button>
               </div>
               {authMode === "register" && (
                 <>
                  <div className={`flex items-center gap-3 p-3.5 rounded-[1.2rem] border-2 ${isDarkMode ? 'bg-black border-zinc-800' : 'bg-white border-slate-300'}`}>
                    <Flag size={16} className="text-amber-500 shrink-0" />
                    <select required className={`bg-transparent outline-none w-full text-[10px] font-black uppercase italic ${isDarkMode ? 'text-white' : 'text-slate-900'} cursor-pointer`} value={formData.country} onChange={e => setFormData({...formData, country: e.target.value, phone: "", province: ""})}>
                      <option value="" disabled className="text-zinc-500">{t('country').toUpperCase()}</option>
                      {COUNTRY_DATA.map(c => <option key={c.name} value={c.name} className={`${isDarkMode ? 'bg-black text-white' : 'bg-white text-slate-900'}`}>{c.flag} {c.name}</option>)}
                    </select>
                  </div>
                  <div className={`flex items-center gap-3 p-3.5 rounded-[1.2rem] border-2 ${isDarkMode ? 'bg-black border-zinc-800' : 'bg-white border-slate-300'}`}>
                    <Phone size={16} className="text-amber-500 shrink-0" />
                    <div className="flex items-center gap-2 w-full">
                      {selectedCountryCode && <span className="text-[10px] font-black text-amber-500">{selectedCountryCode}</span>}
                      <input required type="tel" placeholder={t('phone').toUpperCase()} className={`bg-transparent outline-none w-full text-[10px] font-black uppercase italic ${isDarkMode ? 'text-white' : 'text-slate-900'} placeholder-zinc-500`} value={formData.phone} onChange={e => setFormData({...formData, phone: e.target.value})} />
                    </div>
                  </div>
                  <div className="grid grid-cols-2 gap-3">
                    <div className={`flex items-center gap-3 p-3.5 rounded-[1.2rem] border-2 ${isDarkMode ? 'bg-black border-zinc-800' : 'bg-white border-slate-300'} overflow-hidden`}>
                      <MapPin size={16} className="text-amber-500 shrink-0" />
                      {selectedCountryObj && selectedCountryObj.provinces.length > 0 ? (
                        <select required className={`bg-transparent outline-none w-full text-[10px] font-black italic ${isDarkMode ? 'text-white' : 'text-slate-900'} cursor-pointer truncate`} value={formData.province} onChange={e => setFormData({...formData, province: e.target.value})}>
                          <option value="" disabled className="text-zinc-500">{t('province').toUpperCase()}</option>
                          {selectedCountryObj.provinces.map(p => <option key={p} value={p} className={`${isDarkMode ? 'bg-black text-white' : 'bg-white text-slate-900'}`}>{p}</option>)}
                        </select>
                      ) : (
                        <input required type="text" placeholder={t('province').toUpperCase()} className={`bg-transparent outline-none w-full text-[10px] font-black italic ${isDarkMode ? 'text-white' : 'text-slate-900'} placeholder-zinc-500`} value={formData.province} onChange={e => setFormData({...formData, province: handleTextFormat(e.target.value)})} />
                      )}
                    </div>
                    <div className={`flex items-center gap-3 p-3.5 rounded-[1.2rem] border-2 ${isDarkMode ? 'bg-black border-zinc-800' : 'bg-white border-slate-300'}`}>
                      <Calendar size={16} className="text-amber-500 shrink-0" />
                      <select required className={`bg-transparent outline-none w-full text-[10px] font-black uppercase italic ${isDarkMode ? 'text-white' : 'text-slate-900'} cursor-pointer`} value={formData.age} onChange={e => setFormData({...formData, age: e.target.value})}>
                        <option value="" disabled className="text-zinc-500">{t('age').toUpperCase()}</option>
                        {ageOptions.map(a => <option key={a} value={a} className={`${isDarkMode ? 'bg-black text-white' : 'bg-white text-slate-900'}`}>{a}</option>)}
                      </select>
                    </div>
                  </div>
                 </>
               )}
               <button disabled={loading} className="w-full bg-amber-500 text-black font-black py-4 rounded-[1.2rem] text-[10px] uppercase italic flex items-center justify-center gap-2 hover:bg-amber-400 transition-all shadow-[0_12px_25px_rgba(245,158,11,0.35)] active:scale-95 mt-2">
                 {loading ? <RefreshCw className="animate-spin" /> : (authMode === "login" ? t('enterNow') : t('finishReg'))}
               </button>
            </form>
          </div>
        </div>
      </div>
    );
  }

  return (
    <div className={`min-h-screen ${isDarkMode ? 'bg-[#020617] text-white' : 'bg-white text-slate-900'} pb-28 transition-colors duration-300`}>
      {/* Sidebar Settings */}
      {isSettingsOpen && (
        <div className="fixed inset-0 z-[60] flex animate-in">
          <div className="absolute inset-0 bg-black/80 backdrop-blur-xl" onClick={() => setIsSettingsOpen(false)} />
          <div className={`relative ml-auto h-full w-[80%] max-w-sm p-6 flex flex-col shadow-2xl ${isDarkMode ? 'bg-[#020617] border-l-4 border-zinc-800' : 'bg-white border-l-4 border-slate-100'}`}>
            <div className="flex justify-between items-center mb-6">
              <h2 className="text-lg font-black uppercase italic text-amber-500 tracking-tighter leading-none">{t('settings')}</h2>
              <button onClick={() => setIsSettingsOpen(false)} className={`p-2.5 rounded-xl border-2 ${isDarkMode ? 'border-zinc-800 bg-zinc-900/40' : 'border-slate-200 bg-slate-50'} text-amber-500 active:scale-90 transition-all shadow-xl`}><X size={20}/></button>
            </div>
            <div className="flex-1 space-y-5 overflow-y-auto pr-1">
              <div className="space-y-2">
                <h3 className="text-[8px] font-black uppercase italic text-amber-500/60 tracking-[0.2em]">{t('lang').toUpperCase()} & {t('theme').toUpperCase()}</h3>
                <button onClick={() => {
                   const langs: Lang[] = ['pt', 'en', 'fr', 'es'];
                   const next = langs[(langs.indexOf(lang) + 1) % langs.length];
                   setLang(next);
                   localStorage.setItem("dr_lang", next);
                }} className={`flex items-center justify-between w-full p-3.5 rounded-[1rem] border-2 ${isDarkMode ? 'bg-zinc-800/20 border-zinc-800/40' : 'bg-slate-50 border-slate-200'}`}>
                  <div className="flex items-center gap-3"><Globe size={18} className="text-amber-500" /> <span className={`text-[10px] font-black uppercase italic ${isDarkMode ? '' : 'text-slate-900'}`}>{t('lang')}</span></div>
                  <span className="text-[10px] font-black text-amber-500 uppercase">{lang}</span>
                </button>
                <button onClick={() => { setIsDarkMode(!isDarkMode); localStorage.setItem("dr_theme", !isDarkMode ? "dark" : "light"); }} className={`flex items-center justify-between w-full p-3.5 rounded-[1rem] border-2 ${isDarkMode ? 'bg-zinc-800/20 border-zinc-800/40' : 'bg-slate-50 border-slate-200'}`}>
                  <div className="flex items-center gap-3">{isDarkMode ? <Sun size={18} className="text-amber-500" /> : <Moon size={18} className="text-amber-500" />} <span className={`text-[10px] font-black uppercase italic ${isDarkMode ? '' : 'text-slate-900'}`}>{t('theme')}</span></div>
                  <span className="text-[10px] font-black text-amber-500 uppercase">{isDarkMode ? 'ESCURO' : 'CLARO'}</span>
                </button>
              </div>
              <div className="space-y-2">
                <h3 className="text-[8px] font-black uppercase italic text-amber-500/60 tracking-[0.2em]">STATUS</h3>
                {hasVipAccess ? (
                  <div className={`w-full p-4 rounded-[1rem] border-2 font-black uppercase italic text-[10px] flex flex-col items-center gap-1 shadow-md ${isDarkMode ? 'bg-amber-500/10 border-amber-500/20 text-amber-500' : 'bg-amber-50 border-amber-200 text-amber-600'}`}>
                    <div className="flex items-center gap-2"><Crown size={16} /> {t('vipStatus')}</div>
                    <span className="text-[9px] opacity-70 leading-none">{vipDaysRemaining} {t('daysRemaining')}</span>
                  </div>
                ) : (
                  <a href={`https://wa.me/${SUPPORT_WHATSAPP}?text=${encodeURIComponent(t('vipWhatsappMsg'))}`} target="_blank" className="w-full bg-amber-500 text-black p-3.5 rounded-[1rem] font-black uppercase italic flex items-center justify-center gap-2 shadow-lg active:scale-95 transition-all text-[10px]">
                    <Crown size={18} /> {t('buyVip')}
                  </a>
                )}
              </div>
            </div>
            <button onClick={() => { localStorage.removeItem("dr_user"); setUser(null); }} className={`mt-6 flex items-center justify-center gap-3 p-4 rounded-[1.2rem] border-2 ${isDarkMode ? 'bg-red-500/10 border-red-500/20 text-red-500' : 'bg-red-50 border-red-100 text-red-600'} font-black uppercase italic active:scale-95 transition-all text-[10px]`}><LogOut size={18} /> {t('logout')}</button>
          </div>
        </div>
      )}

      {/* Header */}
      <header className={`sticky top-0 z-40 border-b-4 ${isDarkMode ? 'bg-[#020617] border-zinc-800' : 'bg-white border-slate-200'} px-5 py-3 flex justify-between items-center shadow-lg`}>
        <div className="flex items-center gap-3">
          <div className="bg-amber-500 p-2 rounded-[1rem] shadow-md"><Target size={22} className="text-black" /></div>
          <div>
            <h1 className={`text-lg font-black italic tracking-tighter uppercase leading-none ${isDarkMode ? 'text-white' : 'text-slate-900'}`}>DR <span className="text-amber-500">PALPITES</span></h1>
            <span className="text-[8px] font-black uppercase text-amber-500 block tracking-[0.15em] mt-1 opacity-100">HOJE: {getFirebaseKey().split('-').reverse().join('/')}</span>
          </div>
        </div>
        <button onClick={() => setIsSettingsOpen(true)} className={`p-2.5 rounded-[1rem] border-2 ${isDarkMode ? 'border-zinc-800 bg-zinc-900/50' : 'border-slate-200 bg-white'} text-amber-500 active:scale-90 transition-all shadow-md`}><Menu size={24} /></button>
      </header>

      {/* Ticker */}
      {!hasVipAccess && (
        <a href={`https://wa.me/${SUPPORT_WHATSAPP}?text=${encodeURIComponent(t('vipWhatsappMsg'))}`} target="_blank" className="bg-amber-50 py-2.5 overflow-hidden border-b-2 border-amber-600 relative flex items-center shadow-md cursor-pointer block">
           <div className="marquee-wrapper flex shrink-0">
             <div className="marquee-content inline-block font-black italic uppercase text-[9px] text-black tracking-[0.1em] px-10">{t('tickerText')}</div>
             <div className="marquee-content inline-block font-black italic uppercase text-[9px] text-black tracking-[0.1em] px-10">{t('tickerText')}</div>
           </div>
        </a>
      )}

      {/* Main Content */}
      <main className="max-w-md mx-auto p-4 space-y-5">
        {activeTab === "hoje" && (
          <section className="space-y-5 animate-in">
            <div className="flex justify-between items-start px-1">
              <div className="space-y-1">
                <span className={`text-[9px] font-black uppercase italic tracking-[0.2em] block ${isDarkMode ? 'text-zinc-500' : 'text-slate-400'}`}>BEM-VINDO AO TOPO</span>
                <div className="flex flex-wrap items-center gap-3">
                  <h2 className={`text-3xl font-black italic uppercase leading-none tracking-tighter ${isDarkMode ? 'text-white' : 'text-slate-900'}`}>{user?.username}</h2>
                  {hasVipAccess && (
                    <div className="flex items-center gap-3">
                      <div className="bg-amber-500 text-black px-3 py-1.5 rounded-xl flex items-center gap-2 font-black italic text-[11px] shadow-lg">
                        <Crown size={14} /> VIP
                      </div>
                      <span className="text-emerald-500 font-black italic uppercase text-[12px] tracking-tight drop-shadow-sm">
                        {user?.province}, {user?.country}
                      </span>
                    </div>
                  )}
                </div>
              </div>
            </div>

            {loading ? <div className="py-40 flex justify-center"><RefreshCw className="animate-spin text-amber-500" size={40} /></div> : (
              matches.length === 0 ? <div className={`py-32 text-center font-black uppercase italic tracking-widest text-lg ${isDarkMode ? 'text-zinc-800' : 'text-slate-300'}`}>{t('vazio')}</div> : 
              matches.map((m, i) => {
                const isMatchFullyLocked = m.isVipMatch && !hasVipAccess;
                return (
                  <div key={i} className={`border-4 rounded-[2.5rem] overflow-hidden shadow-xl ${isDarkMode ? 'bg-zinc-900/60 border-zinc-800' : 'bg-white border-slate-200'}`}>
                    <div className={`p-3.5 flex justify-between items-center text-[9px] font-black uppercase border-b-2 ${isDarkMode ? 'bg-black/60 border-zinc-800' : 'bg-slate-50 border-slate-100'}`}>
                      <span className={`${isDarkMode ? 'text-white' : 'text-slate-600'} tracking-widest`}>{m.league}</span> 
                      {m.isVipMatch && <span className="bg-amber-500 text-black px-2 py-0.5 rounded flex items-center gap-1 text-[7px]"><Crown size={8}/> VIP</span>}
                      <span className="text-amber-500 tracking-[0.05em]">{m.startTime}</span>
                    </div>
                    <div className="p-5">
                      <h3 className={`text-lg font-black uppercase italic tracking-tighter text-center mb-5 leading-tight ${isDarkMode ? 'text-white' : 'text-slate-900'}`}>{m.homeTeam} <span className="text-[10px] text-amber-500/50 mx-2 font-black italic">vs</span> {m.awayTeam}</h3>
                      <div className="space-y-2">
                        {isMatchFullyLocked ? (
                          <div className="bg-amber-500 p-8 rounded-[1.5rem] flex flex-col items-center justify-center gap-3 shadow-lg border-2 border-black/10">
                            <LockKeyhole size={40} className="text-black" />
                            <span className="text-black font-black uppercase italic text-center text-[10px] leading-tight">{t('vipOnlyMatch')}</span>
                          </div>
                        ) : (
                          m.tips?.map((tip: any, idx: number) => {
                            // Regra de visibilidade para usuários normais:
                            // Se 4 palpites, bloqueia 1 (mostra 3). Se 5 ou mais, mostra apenas 3.
                            const maxVisible = m.tips.length === 4 ? 3 : (m.tips.length >= 5 ? 3 : m.tips.length);
                            const isTipLocked = !hasVipAccess && idx >= maxVisible;
                            const selectionDisplay = cleanSelectionText(tip.market, tip.selection);

