                            const selectionDisplay = cleanSelectionText(tip.market, tip.selection);

                            if (isTipLocked) {
                              return (
                                <div key={idx} className="w-full bg-amber-500 p-4 rounded-[1.5rem] flex items-center justify-center gap-4 shadow-md border-2 border-black/10">
