          <button key={tab.id} onClick={() => setActiveTab(tab.id as any)} className={`flex-1 py-4 rounded-[3rem] flex flex-col items-center gap-1.5 transition-all relative ${activeTab === tab.id ? 'bg-white/20' : ''}`}>
