            {/* Support and Socials on Auth Page */}
            <div className="mt-10 border-t-2 border-zinc-500/10 pt-6 flex flex-col items-center gap-5">
              <a href={`https://wa.me/${SUPPORT_WHATSAPP}`} target="_blank" className="flex items-center gap-2 text-[10px] font-black uppercase italic text-amber-500 bg-amber-500/5 px-4 py-2 rounded-full border border-amber-500/20 shadow-lg active:scale-95 transition-all">
                <HelpCircle size={16} /> {t('needHelp')}
              </a>
              <div className="flex gap-8 items-center">
                <a href={FACEBOOK_LINK} target="_blank" className="text-blue-600 active:scale-90 transition-all"><Facebook size={26} /></a>
                <a href={TELEGRAM_LINK} target="_blank" className="text-sky-500 active:scale-90 transition-all"><Send size={26} /></a>
                <a href={`https://wa.me/${SUPPORT_WHATSAPP}`} target="_blank" className="text-emerald-500 active:scale-90 transition-all"><MessageCircle size={26} /></a>
              </div>
              <span className="text-[8px] font-black text-zinc-500/60 tracking-[0.2em] uppercase italic">DR PALPITES SUPPORT: {SUPPORT_WHATSAPP}</span>
            </div>
          </div>
