  };

  const selectedCountryObj = useMemo(() => COUNTRY_DATA.find(c => c.name === formData.country), [formData.country]);
  const selectedCountryCode = useMemo(() => selectedCountryObj?.code || "", [selectedCountryObj]);

  // Safe Translation Helper
  const t = useCallback((key: keyof typeof TRANSLATIONS['pt']) => {
    const langObj = (TRANSLATIONS as any)[lang] || TRANSLATIONS['pt'];
    return langObj[key] || (TRANSLATIONS['pt'] as any)[key] || key;
  }, [lang]);

  const addToast = useCallback((message: string, type: 'success' | 'error' = 'success') => {
    const id = Date.now();
    setToasts(prev => [...prev, { id, message, type }]);
    setTimeout(() => setToasts(prev => prev.filter(toast => toast.id !== id)), 3000);
  }, []);

  const hasVipAccess = useMemo(() => {
    const isVip = user?.isVip === true;
    const isExpired = (user?.vipExpiry && user.vipExpiry > 0) ? Date.now() > user.vipExpiry : false;
    return isVip && !isExpired;
  }, [user]);

  const vipDaysRemaining = useMemo(() => {
    if (!user?.vipExpiry) return 0;
    return Math.max(0, Math.ceil((user.vipExpiry - Date.now()) / (1000 * 60 * 60 * 24)));
  }, [user]);

  useEffect(() => {
    const checkAlert = async () => {
      try {
        const res = await fetch(`${FIREBASE_URL}/Alerta/chave.json`);
        const data = await res.json();
        if (data && data.mostrar === "true") {
          const dismissedToken = localStorage.getItem("dr_dismissed_alert");
          if (dismissedToken !== data.token) {
            setActiveAlert(data);
          }
        } else {
          setActiveAlert(null);
        }
      } catch (e) {}
    };
    checkAlert();
    const interval = setInterval(checkAlert, 15000);
    return () => clearInterval(interval);
  }, []);

  useEffect(() => {
    const savedUser = localStorage.getItem("dr_user");
    if (savedUser) {
      const parsed = JSON.parse(savedUser);
      setUser(parsed);
      fetch(`${FIREBASE_URL}/usuarios/${parsed.uid}.json`)
        .then(res => res.json())
        .then(data => { if (data) { setUser(data); localStorage.setItem("dr_user", JSON.stringify(data)); } })
        .catch(() => {});
    }
    const savedLang = localStorage.getItem("dr_lang") as Lang;
    if (savedLang) setLang(savedLang);
    const savedTheme = localStorage.getItem("dr_theme");
    if (savedTheme) setIsDarkMode(savedTheme === "dark");
    setIsAuthenticating(false);
  }, []);

  useEffect(() => {
    if (user) {
      loadFirebaseData();
      const stored = localStorage.getItem(`dr_tickets_${user.uid || user.username}`);
      if (stored) setSavedTickets(JSON.parse(stored));
    }
  }, [user]);

  const loadFirebaseData = async () => {
    setLoading(true);
    const dateKey = getFirebaseKey();
    try {
      const [standardRes, matchesRes, fichasRes, accumulatorsRes] = await Promise.all([
        fetch(`${FIREBASE_URL}/predictions/${dateKey}.json`),
        fetch(`${FIREBASE_URL}/predictions/matches.json`),
        fetch(`${FIREBASE_URL}/predictions/fichas.json`),
        fetch(`${FIREBASE_URL}/predictions/acumulators.json`)
      ]);

      const standardData = await standardRes.json();
      const matchesData = await matchesRes.json();
      const fichasData = await fichasRes.json();
      const accumulatorsData = await accumulatorsRes.json();

      // Process Matches
      let aggregatedMatches: Match[] = [];

      // Standard Date Node
      if (standardData && standardData.matches) {
        const m = Array.isArray(standardData.matches) ? standardData.matches : Object.values(standardData.matches);
        aggregatedMatches = [...aggregatedMatches, ...m];
      }

      // Root Matches Node
      if (matchesData) {
        Object.entries(matchesData).forEach(([key, val]) => {
          const isVip = key === "empates";
          const list = Array.isArray(val) ? val : Object.values(val);
          const processed = list.map((item: any) => ({ ...item, isVipMatch: isVip || item.isVipMatch }));
          aggregatedMatches = [...aggregatedMatches, ...processed];
        });
      }

      // Process Accumulators / Fichas
      let aggregatedFichas: Ficha[] = [];

      // Standard Date Node
      const rawF = standardData ? (standardData.fichas || standardData.accumulators) : null;
      if (rawF) {
        const f = Array.isArray(rawF) ? rawF : Object.values(rawF);
        aggregatedFichas = [...aggregatedFichas, ...f];
      }

      // Root Fichas Node
      if (fichasData) {
        Object.values(fichasData).forEach((val: any) => {
          const list = Array.isArray(val) ? val : (typeof val === 'object' ? Object.values(val) : [val]);
          aggregatedFichas = [...aggregatedFichas, ...list];
        });
      }

      // Root Accumulators Node
      if (accumulatorsData) {
        Object.values(accumulatorsData).forEach((val: any) => {
          const list = Array.isArray(val) ? val : (typeof val === 'object' ? Object.values(val) : [val]);
          aggregatedFichas = [...aggregatedFichas, ...list];
        });
      }

      const finalizedFichas = aggregatedFichas
        .filter(f => f && typeof f === 'object')
        .map((ficha: any) => ({
          ...ficha,
          selections: ficha.selections ? (Array.isArray(ficha.selections) ? ficha.selections : Object.values(ficha.selections)) : []
        }));

      setMatches(aggregatedMatches);
      setFichas(finalizedFichas);
    } catch (e) {
      console.error("Firebase fetch error:", e);
    } finally {
      setLoading(false);
    }
  };

  const handleAuth = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);
    try {
      const res = await fetch(`${FIREBASE_URL}/usuarios.json`);
      const all = await res.json();
      if (authMode === "register") {
        const finalPhone = `${selectedCountryCode} ${formData.phone}`.trim();
        if (selectedCountryObj) {
          if (formData.phone.length < selectedCountryObj.min || formData.phone.length > selectedCountryObj.max) {
             addToast(t('invalidPhone'), "error");
             setLoading(false);
             return;
          }
        }
        if (Object.values(all || {}).some((u: any) => (u as any).phone === finalPhone)) {
          addToast(t('accountExists'), "error");
          setLoading(false);
          return;
        }
        const uid = Date.now().toString();
        const newUser: UserProfile = { 
          uid, username: formData.username, country: formData.country === "OUTRO" ? formData.customCountry : formData.country, 
          password: formData.password, phone: finalPhone, province: formData.province, age: formData.age, isVip: false, vipExpiry: 0 
        };
        await fetch(`${FIREBASE_URL}/usuarios/${uid}.json`, { method: 'PUT', body: JSON.stringify(newUser) });
        setUser(newUser); 
        localStorage.setItem("dr_user", JSON.stringify(newUser));
        addToast(t('accCreated'));
      } else if (authMode === "login") {
        const u = (Object.values(all || {}) as UserProfile[]).find(x => x?.username?.toLowerCase() === formData.username?.toLowerCase());
        if (!u || u.password !== formData.password) { addToast(t(u ? 'wrongPass' : 'userNotFound'), "error"); setLoading(false); return; }
        setUser(u); 
        localStorage.setItem("dr_user", JSON.stringify(u));
        addToast(t('welcomeBack'));
      }
    } catch { addToast(t('authError'), "error"); } finally { setLoading(false); }
  };

  const handleRecovery = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);
    try {
      const res = await fetch(`${FIREBASE_URL}/usuarios.json`);
      const all = await res.json();
      const finalPhone = `${selectedCountryCode} ${formData.phone}`.trim();
      if (recoveryStep === "verify") {
        const u = (Object.values(all || {}) as UserProfile[]).find(x => 
          x?.phone === finalPhone && 
          x?.country === formData.country && 
          x?.province === formData.province
        );
        if (u) {
          setRecoveredUser(u);
          setRecoveryStep("reset");
          addToast(t('userFound') + " " + u.username);
