             </div>
          </div>

          <div className={`p-6 rounded-[2.2rem] border-4 ${isDarkMode ? 'bg-zinc-900/80 border-zinc-800' : 'bg-slate-50 border-slate-200'} shadow-2xl backdrop-blur-xl`}>
            {authMode !== "recovery" ? (
