                <div className="space-y-3">
                  {Object.entries(groupedBetSlip).map(([matchName, selections]: any) => (
                    <div key={matchName} className={`p-5 rounded-[1.8rem] border-4 shadow-lg ${isDarkMode ? 'bg-zinc-900/60 border-zinc-800' : 'bg-white border-slate-200'}`}>
                      <p className="text-[11px] font-black text-amber-500 uppercase italic mb-3 tracking-widest border-b-2 border-amber-500/10 pb-2">{matchName}</p>
                      <div className="space-y-3">
                        {selections.map((item: any) => (
                          <div key={item.id} className="flex justify-between items-center animate-in">
                             <div className="leading-tight">
                                <p className={`font-black uppercase text-[10px] italic tracking-tighter ${isDarkMode ? 'text-white' : 'text-slate-900'}`}>{item.market}: <span className="text-amber-500">{cleanSelectionText(item.market, item.selection)}</span></p>
                             </div>
                             <div className="flex items-center gap-3">
                                <span className={`font-black text-lg italic tracking-tighter ${isDarkMode ? 'text-white' : 'text-slate-900'}`}>@{item.odds.toFixed(2)}</span>
                                <button onClick={() => setBetSlip(prev => prev.filter(i => i.id !== item.id))} className={`p-1.5 rounded-lg active:scale-90 transition-all ${isDarkMode ? 'text-red-500' : 'text-red-600'}`}><Trash2 size={16} /></button>
                             </div>
                          </div>
                        ))}
                      </div>
                    </div>
                  ))}
                </div>
                <div className={`p-5 rounded-[1.8rem] border-4 shadow-lg ${isDarkMode ? 'bg-zinc-900/60 border-zinc-800' : 'bg-white border-slate-200'}`}>
                  <label className="text-[9px] font-black uppercase text-amber-500 block mb-2 tracking-widest">{t('stakeAmount')}</label>
                  <div className="flex items-center gap-3 bg-black/20 rounded-xl p-3 border-2 border-amber-500/30">
                    <DollarSign size={20} className="text-amber-500" />
                    <input type="number" value={manualStake} onChange={(e) => setManualStake(e.target.value)} className={`bg-transparent outline-none w-full font-black text-lg ${isDarkMode ? 'text-white' : 'text-slate-900'}`} placeholder="0" />
                  </div>
                </div>
                <div className="mt-8 p-8 bg-amber-500 rounded-[2.5rem] text-black shadow-xl border-b-8 border-amber-600">
                   <div className="grid grid-cols-2 gap-4 mb-6 border-b-4 border-black/10 pb-4">
                      <div className="flex flex-col">
                        <span className="font-black uppercase italic text-[10px] tracking-tighter opacity-70">{t('totalOdds').toUpperCase()}</span>
                        <span className="text-3xl font-black tracking-tighter italic leading-none">@{totalBetSlipOdds.toFixed(2)}</span>
                      </div>
                      <div className="flex flex-col items-end">
                        <span className="font-black uppercase italic text-[10px] tracking-tighter opacity-70">{t('potentialWinnings')}</span>
                        <span className="text-3xl font-black tracking-tighter italic leading-none">{potentialWinningsCalculation} <span className="text-[12px] opacity-60">kz</span></span>
                      </div>
                   </div>
                   <button onClick={() => {
                     const ticket = { id: Date.now(), date: new Date().toLocaleString(), items: [...betSlip], totalOdds: totalBetSlipOdds.toFixed(2), stake: manualStake, winnings: potentialWinningsCalculation };
                     const updated = [ticket, ...savedTickets]; setSavedTickets(updated);
                     localStorage.setItem(`dr_tickets_${user?.uid || user?.username}`, JSON.stringify(updated));
                     setBetSlip([]); setActiveTab("guardados"); addToast(t('saved'));
                   }} className="w-full bg-black text-white py-5 rounded-[1.5rem] font-black uppercase italic text-[11px] flex items-center justify-center gap-3 active:scale-95 transition-all shadow-xl border-b-4 border-zinc-800"><Save size={24} /> {t('saved').toUpperCase()}</button>
                </div>
              </div>
            }
          </section>
        )}

        {activeTab === "guardados" && (
          <section className="space-y-6 animate-in pb-20">
             <h3 className={`text-xl font-black italic uppercase px-3 tracking-tighter ${isDarkMode ? 'text-white' : 'text-slate-900'}`}>{t('myTickets')}</h3>
             {savedTickets.length === 0 ? <div className={`py-40 text-center font-black uppercase italic tracking-widest text-lg ${isDarkMode ? 'text-zinc-800' : 'text-slate-300'}`}>{t('vazio')}</div> : 
               savedTickets.map(tkt => (
                 <div key={tkt.id} className={`p-6 border-4 rounded-[2.5rem] shadow-xl ${isDarkMode ? 'bg-zinc-900/60 border-zinc-800' : 'bg-white border-slate-200'} relative space-y-4`}>
                    <div className="flex justify-between items-start">
                      <div className={`flex items-center gap-2 ${isDarkMode ? 'text-white/50' : 'text-slate-400'}`}><Calendar size={16} /><span className="text-[9px] font-black uppercase italic tracking-widest">{tkt.date}</span></div>
                      <button onClick={() => { const u = savedTickets.filter(t => t.id !== tkt.id); setSavedTickets(u); localStorage.setItem(`dr_tickets_${user?.uid || user?.username}`, JSON.stringify(u)); }} className={`p-2.5 rounded-xl border-2 active:scale-90 transition-all shadow-md ${isDarkMode ? 'bg-red-500/10 text-red-500 border-red-500/20' : 'bg-red-50 text-red-600 border-red-100'}`}><Trash2 size={18} /></button>
                    </div>
                    <div className={`p-4 rounded-xl space-y-3 ${isDarkMode ? 'bg-black/40' : 'bg-slate-50'}`}>
                      {tkt.items.map((it: any, idx: number) => (
                        <div key={idx} className={`text-[10px] pb-2 border-b last:border-0 ${isDarkMode ? 'border-zinc-800' : 'border-slate-200'}`}>
                          <p className="font-black text-amber-500 uppercase">{it.matchName}</p>
                          <p className={`font-black opacity-80 ${isDarkMode ? 'text-white' : 'text-slate-700'}`}>{it.market}: {cleanSelectionText(it.market, it.selection)} @{parseFloat(it.odds).toFixed(2)}</p>
                        </div>
                      ))}
                    </div>
                    <div className="grid grid-cols-2 gap-2">
                      <div className={`p-3 rounded-xl border-2 ${isDarkMode ? 'bg-amber-500/5 border-amber-500/20' : 'bg-amber-50 border-amber-100'}`}>
                        <span className={`text-[8px] font-black uppercase block opacity-50 ${isDarkMode ? 'text-white' : 'text-slate-600'}`}>{t('stake').toUpperCase()}</span>
                        <span className="text-sm font-black text-amber-500">{tkt.stake || '0'} kz</span>
                      </div>
                      <div className={`p-3 rounded-xl border-2 ${isDarkMode ? 'bg-emerald-500/5 border-emerald-500/20' : 'bg-emerald-50 border-emerald-100'}`}>
                        <span className={`text-[8px] font-black uppercase block opacity-50 ${isDarkMode ? 'text-white' : 'text-slate-600'}`}>{t('totalWinnings').toUpperCase()}</span>
                        <span className="text-sm font-black text-emerald-500">{tkt.winnings || '0'}</span>
                      </div>
                    </div>
                 </div>
               ))
             }
          </section>
        )}

        {activeTab === "chat" && (
          <section className="animate-in flex flex-col h-[70vh] pb-20">
            <h3 className={`text-xl font-black italic uppercase px-3 tracking-tighter mb-4 ${isDarkMode ? 'text-white' : 'text-slate-900'}`}>{t('chat')}</h3>
            <div className={`flex-1 overflow-y-auto p-4 space-y-4 rounded-[2rem] border-4 ${isDarkMode ? 'bg-zinc-900/60 border-zinc-800' : 'bg-slate-50 border-slate-200'}`}>
              {chatMessages.length === 0 ? <div className="text-center py-20 text-[10px] uppercase font-black opacity-30">{t('noMessages')}</div> :
                chatMessages.map(msg => (
                  <div key={msg.id} className={`flex gap-3 ${msg.uid === user.uid ? 'flex-row-reverse' : ''}`}>
                    <div className="w-8 h-8 rounded-full border-2 border-amber-500 overflow-hidden shrink-0 shadow-lg">
                      {msg.profilePic ? <img src={msg.profilePic} className="w-full h-full object-cover" /> : <User size={16} className="m-auto mt-1" />}
                    </div>
                    <div className={`max-w-[70%] space-y-1 ${msg.uid === user.uid ? 'text-right' : 'text-left'}`}>
                       <p className="text-[8px] font-black text-amber-500 uppercase">{msg.username}</p>
                       <div className={`p-3 rounded-2xl text-[11px] font-bold ${msg.uid === user.uid ? 'bg-amber-500 text-black rounded-tr-none' : (isDarkMode ? 'bg-zinc-800 text-white rounded-tl-none' : 'bg-white text-slate-900 rounded-tl-none shadow-md')}`}>
                         {msg.text}
                       </div>
                    </div>
                  </div>
                ))
              }
              <div ref={chatEndRef} />
            </div>
            <div className="mt-4 flex gap-2">
               <input 
                 type="text" 
                 value={chatInput} 
                 onChange={e => setChatInput(e.target.value)} 
                 onKeyDown={e => e.key === 'Enter' && handleSendMessage()}
                 placeholder={t('typeMessage')}
                 className={`flex-1 p-4 rounded-2xl font-black text-[11px] border-4 focus:border-amber-500 transition-all ${isDarkMode ? 'bg-zinc-900 border-zinc-800 text-white' : 'bg-white border-slate-200 text-slate-900'}`} 
               />
               <button onClick={handleSendMessage} className="bg-amber-500 text-black p-4 rounded-2xl shadow-xl active:scale-90 transition-all"><Send size={24} /></button>
            </div>
          </section>
        )}
      </main>

      <nav className={`fixed bottom-6 left-1/2 -translate-x-1/2 w-[94%] max-w-[500px] p-2 rounded-[3.5rem] flex gap-1 z-50 border-4 shadow-2xl transition-all ${isDarkMode ? 'bg-amber-500 border-amber-600/50' : 'bg-black border-zinc-800'}`}>
        {[
          { id: 'hoje', icon: LayoutDashboard, label: t('palpites') },
          { id: 'acumulador', icon: Layers, label: t('fichas') },
          { id: 'chat', icon: MessageCircle, label: t('chat') },
          { id: 'boletim', icon: Ticket, label: t('boletim'), count: betSlip.length },
          { id: 'guardados', icon: Save, label: t('guardados') }
        ].map(tab => (
          <button key={tab.id} onClick={() => setActiveTab(tab.id as any)} className={`flex-1 py-4 rounded-[3rem] flex flex-col items-center gap-1.5 transition-all relative ${activeTab === tab.id ? 'bg-white/20' : ''}`}>
            <tab.icon size={20} className="text-white drop-shadow-[0_1.5px_1.5px_rgba(0,0,0,1)]" strokeWidth={3} />
            <span className="text-[7px] uppercase font-black tracking-tighter leading-none text-white drop-shadow-[0_1.5px_1.5px_rgba(0,0,0,1)]">{tab.label}</span>
            {tab.count ? <span className="absolute top-1 right-2 bg-red-600 text-white text-[8px] w-5 h-5 rounded-full flex items-center justify-center border-2 border-white font-black animate-pulse">{tab.count}</span> : null}
          </button>
        ))}
      </nav>

      {activeAlert && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-8 bg-black/80 backdrop-blur-md animate-in">
          <div className="bg-white rounded-[2.5rem] p-8 w-full max-w-[320px] shadow-[0_0_50px_rgba(245,158,11,0.3)] space-y-5 text-center border-4 border-amber-500">
            <div className="mx-auto bg-amber-500 w-16 h-16 rounded-2xl flex items-center justify-center shadow-lg border-2 border-black">
              <Bell size={32} className="text-black animate-bounce" />
            </div>
            <div className="space-y-3">
              <h3 className="text-black font-black text-2xl italic uppercase tracking-tighter leading-none">{activeAlert.titulo}</h3>
              <p className="text-zinc-600 font-bold text-[13px] leading-relaxed italic uppercase border-t-2 border-zinc-100 pt-3">{activeAlert.mensagem}</p>
            </div>
            <button 
              onClick={() => {
                if (activeAlert.token) localStorage.setItem("dr_dismissed_alert", activeAlert.token);
                setActiveAlert(null);
              }}
              className="w-full bg-black text-white py-4 rounded-2xl font-black uppercase italic tracking-widest active:scale-95 transition-all shadow-xl border-b-4 border-zinc-800"
            >{t('ok')}</button>
          </div>
        </div>
      )}

      <style dangerouslySetInnerHTML={{ __html: `
        @keyframes slideUp { from { transform: translateY(20px); opacity: 0; } to { transform: translateY(0); opacity: 1; } }
        .animate-in { animation: slideUp 0.6s cubic-bezier(0.16, 1, 0.3, 1) forwards; }
        .marquee-wrapper { animation: marquee 70s linear infinite; }
        @keyframes marquee { 0% { transform: translateX(0); } 100% { transform: translateX(-50%); } }
        ::-webkit-scrollbar { display: none; }
        * { -webkit-tap-highlight-color: transparent; outline: none; }
        body { overflow-x: hidden; -webkit-font-smoothing: antialiased; font-family: 'Inter', sans-serif; font-weight: 900; background-color: ${isDarkMode ? '#020617' : '#ffffff'}; font-size: 13px; }
        input::placeholder { font-weight: 900; opacity: 1; color: #4b5563; }
        select { -webkit-appearance: none; appearance: none; cursor: pointer; border: none; }
        option { background: #000; color: #fff; font-weight: 900; }
        .marquee-content { white-space: nowrap; }
      `}} />

      <div className="fixed top-6 left-1/2 -translate-x-1/2 z-[200] space-y-2 w-[90%] max-w-[300px]">
        {toasts.map(toast => (
          <div key={toast.id} className={`p-4 rounded-[1.2rem] shadow-2xl border-2 flex items-center justify-center gap-3 animate-in ${toast.type === 'error' ? 'bg-red-500 border-red-600 text-white' : 'bg-emerald-500 border-emerald-600 text-white'}`}>
            <span className="text-[10px] font-black uppercase italic tracking-widest">{toast.message}</span>
          </div>
        ))}
      </div>
    </div>
  );
};

const mountApp = () => {
  const container = document.getElementById("root");
  if (container) {
    const root = (container as any)._reactRoot || ReactDOM.createRoot(container);
    (container as any)._reactRoot = root;
    root.render(<React.StrictMode><App /></React.StrictMode>);
  }
};
document.readyState === 'loading' ? document.addEventListener('DOMContentLoaded', mountApp) : mountApp();
